// Exercise library — rebuilt from fitness_exercise_muscle_audit_v2.xlsx
// Muscle taxonomy: 20 specific groups across Upper Body / Core / Lower Body / Other
// clickableSelections → which muscle filter buttons surface this exercise
// anatomicalHighlight → all muscles lit on the body diagram

export type MuscleGroup =
  | "Chest" | "Lats" | "Upper Back" | "Traps" | "Shoulders"
  | "Biceps" | "Triceps" | "Forearms" | "Neck"
  | "Abs" | "Obliques" | "Lower Back"
  | "Glutes" | "Quads" | "Hamstrings" | "Calves" | "Adductors" | "Abductors"
  | "Cardio" | "Full Body";

export type AppSection = "Upper Body" | "Core" | "Lower Body" | "Multiple" | "Other";

export type ExerciseType =
  | "barbell" | "dumbbell" | "cable" | "bodyweight" | "machine"
  | "skill" | "cardio" | "kettlebell" | "full body";

export interface ExerciseDef {
  name: string;
  appSection: AppSection;
  /** Muscle group filter buttons this exercise appears under */
  clickableSelections: MuscleGroup[];
  primaryMuscles: MuscleGroup[];
  secondaryMuscles: MuscleGroup[];
  /** All muscles to highlight on the anatomical figure */
  anatomicalHighlight: MuscleGroup[];
  type: ExerciseType;
  isHold: boolean;
}

