/** Return exercises that appear under a given clickable muscle group */
export function getExercisesByMuscle(muscle: MuscleGroup): ExerciseDef[] {
  return EXERCISE_LIBRARY.filter(ex => ex.clickableSelections.includes(muscle));
}

